excels.excel:

EXPORT WITH SHEET="销项发票台账", HEADER=true,
    MAPPING={"a":"发票号码","b":"开票日期","c":"客户名称","d":"不含税金额","e":"税率","f":"税额","g":"价税合计","h":"开票状态"},
    FORMAT={"b":"yyyy-MM-dd","d":"#,##0.00","e":"0%","f":"#,##0.00","g":"#,##0.00"},
    FORMULAS={
        F2:'D2*E2',G2:'D2+F2',
        F3:'D3*E3',G3:'D3+F3',
        F4:'D4*E4',G4:'D4+F4',
        F5:'D5*E5',G5:'D5+F5',
        F6:'D6*E6',G6:'D6+F6',
        D7:'SUM(D2:D6)',F7:'SUM(F2:F6)',G7:'D7+F7'
    },
    STYLE={
        ROW 7:{bold:true,fillPattern:solid_foreground,fillForegroundColor:lightYellow,alignment:right,verticalAlignment:center},
        H6:{color:red,bold:true}
    }
